using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        PlayerMovement pm = GameObject.FindFirstObjectByType<PlayerMovement>();
        if (pm == null)
        {
            result.LogError("No PlayerMovement found.");
            return;
        }

        GameObject player = pm.gameObject;
        CharacterController cc = player.GetComponent<CharacterController>();

        result.Log("Player position: {0}", player.transform.position);
        result.Log("CC center={0}, height={1}, radius={2}, skinWidth={3}, stepOffset={4}, minMoveDistance={5}",
            cc.center, cc.height, cc.radius, cc.skinWidth, cc.stepOffset, cc.minMoveDistance);
        result.Log("CC isGrounded (current): {0}", cc.isGrounded);

        float bottomY = player.transform.position.y + cc.center.y - cc.height * 0.5f;
        result.Log("Computed CC bottom Y (world): {0}", bottomY);

        // Raycast straight down from a point above the player to find the floor
        Vector3 rayOrigin = player.transform.position + Vector3.up * 5f;
        if (Physics.Raycast(rayOrigin, Vector3.down, out RaycastHit hit, 50f))
        {
            result.Log("Floor hit: {0} at Y={1}, distance from player bottom to floor = {2}", hit.collider.name, hit.point.y, bottomY - hit.point.y);
        }
        else
        {
            result.LogWarning("No floor hit found below player within 50 units.");
        }
    }
}

