using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        PlayerMovement pm = GameObject.FindFirstObjectByType<PlayerMovement>();
        if (pm == null)
        {
            result.LogError("No PlayerMovement found.");
            return;
        }

        GameObject player = pm.gameObject;
        CharacterController cc = player.GetComponent<CharacterController>();

        float bottomOffset = cc.center.y - cc.height * 0.5f;

        Vector3 feetPoint = new Vector3(player.transform.position.x, player.transform.position.y + bottomOffset, player.transform.position.z);

        if (Physics.Raycast(feetPoint + Vector3.up * 2f, Vector3.down, out RaycastHit hit, 10f))
        {
            result.RegisterObjectModification(player.transform);

            float targetBottomY = hit.point.y + cc.skinWidth;
            Vector3 newPos = player.transform.position;
            newPos.y = targetBottomY - bottomOffset;
            player.transform.position = newPos;

            EditorSceneManager.MarkSceneDirty(player.scene);

            result.Log("Player snapped to floor '{0}'. New position: {1}", hit.collider.name, player.transform.position);
        }
        else
        {
            result.LogError("No floor found below player.");
        }
    }
}

