using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        PlayerMovement pm = GameObject.FindFirstObjectByType<PlayerMovement>();
        if (pm == null)
        {
            result.LogError("No PlayerMovement found.");
            return;
        }

        GameObject player = pm.gameObject;
        CharacterController cc = player.GetComponent<CharacterController>();

        float bottomOffset = cc.center.y - cc.height * 0.5f;

        // Use a fixed known-good X/Z from before (original position was around Y=1.5, X/Z unchanged)
        Vector3 currentPos = player.transform.position;
        Vector3 feetPoint = new Vector3(currentPos.x, currentPos.y + bottomOffset, currentPos.z);

        RaycastHit[] hits = Physics.RaycastAll(feetPoint + Vector3.up * 2f, Vector3.down, 20f);
        System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));

        RaycastHit? floorHit = null;
        foreach (var hit in hits)
        {
            if (hit.transform == player.transform || hit.transform.IsChildOf(player.transform))
            {
                continue;
            }
            floorHit = hit;
            break;
        }

        if (floorHit.HasValue)
        {
            result.RegisterObjectModification(player.transform);

            float targetBottomY = floorHit.Value.point.y + cc.skinWidth;
            Vector3 newPos = player.transform.position;
            newPos.y = targetBottomY - bottomOffset;
            player.transform.position = newPos;

            EditorSceneManager.MarkSceneDirty(player.scene);

            result.Log("Player snapped to floor '{0}' at Y={1}. New player position: {2}", floorHit.Value.collider.name, floorHit.Value.point.y, player.transform.position);
        }
        else
        {
            result.LogError("No floor found below player (excluding self).");
        }
    }
}

