using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        PlayerMovement pm = GameObject.FindFirstObjectByType<PlayerMovement>();
        if (pm == null)
        {
            result.LogError("No PlayerMovement found.");
            return;
        }

        GameObject player = pm.gameObject;
        CharacterController cc = player.GetComponent<CharacterController>();
        MeshFilter rootMeshFilter = player.GetComponent<MeshFilter>();
        MeshRenderer rootMeshRenderer = player.GetComponent<MeshRenderer>();

        if (rootMeshFilter == null || rootMeshRenderer == null)
        {
            result.LogError("Player does not have MeshFilter/MeshRenderer directly on the root (already restructured?).");
            return;
        }

        GameObject model = new GameObject("Model");
        result.RegisterObjectCreation(model);
        model.transform.SetParent(player.transform, false);
        model.transform.localPosition = new Vector3(0f, -cc.skinWidth, 0f);
        model.transform.localRotation = Quaternion.identity;
        model.transform.localScale = Vector3.one;

        MeshFilter modelFilter = model.AddComponent<MeshFilter>();
        modelFilter.sharedMesh = rootMeshFilter.sharedMesh;

        MeshRenderer modelRenderer = model.AddComponent<MeshRenderer>();
        modelRenderer.sharedMaterials = rootMeshRenderer.sharedMaterials;
        modelRenderer.shadowCastingMode = rootMeshRenderer.shadowCastingMode;
        modelRenderer.receiveShadows = rootMeshRenderer.receiveShadows;

        result.DestroyObject(rootMeshRenderer);
        result.DestroyObject(rootMeshFilter);

        EditorSceneManager.MarkSceneDirty(player.scene);

        result.Log("Moved player visual mesh to child 'Model' with localPosition.y = {0} (skinWidth = {1})", model.transform.localPosition.y, cc.skinWidth);
    }
}

