using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        PropDisguise pd = GameObject.FindFirstObjectByType<PropDisguise>();
        if (pd == null)
        {
            result.LogError("PropDisguise not found.");
            return;
        }

        SerializedObject so = new SerializedObject(pd);
        SerializedProperty prop = so.FindProperty("playerRenderers");
        result.Log("playerRenderers array size (serialized): {0}", prop.arraySize);

        Renderer[] runtimeRenderers = pd.GetComponentsInChildren<Renderer>();
        result.Log("GetComponentsInChildren<Renderer> count: {0}", runtimeRenderers.Length);
        foreach (var r in runtimeRenderers)
        {
            result.Log(" - {0} on {1}", r.GetType().Name, r.gameObject.name);
        }

        GameObject model = pd.transform.Find("Model")?.gameObject;
        result.Log("Model child found: {0}, localPosition: {1}", model != null, model != null ? model.transform.localPosition.ToString() : "N/A");

        // Confirm root no longer has MeshFilter/MeshRenderer
        result.Log("Root has MeshFilter: {0}, MeshRenderer: {1}", pd.GetComponent<MeshFilter>() != null, pd.GetComponent<MeshRenderer>() != null);
    }
}

